23	static struct XshimPixmap *pixmap_new(int w, int h, int depth) {
24	  struct XshimPixmap *pm = (struct XshimPixmap *)calloc(1, sizeof(*pm));
25	  if (!pm) return NULL;
26	  pm->w = w;
27	  pm->h = h;
28	  pm->depth = depth;
29	  pm->stride = (w + 7) / 8;
30	  if (depth == 1)
31	    pm->bits = (uint8_t *)malloc((size_t)pm->stride * (size_t)h);
32	  else
33	    pm->rgb = (uint16_t *)malloc((size_t)w * (size_t)h * sizeof(uint16_t));
34	  if (!pm->bits && !pm->rgb) {
35	    pixmap_free(pm);
36	    return NULL;
37	  }
38	  return pm;
39	}
