79	Pixmap image_data_to_pixmap(Display *dpy, Window win, const unsigned char *data,
80	                            unsigned long size, int *width_ret,
81	                            int *height_ret, Pixmap *mask_ret) {
82	  (void)win;
83	  *width_ret = *height_ret = 0;
84	  *mask_ret = None;
85	  if (size < 8 || memcmp(data, "565M", 4) != 0) return None;
86	
87	  const unsigned w = le16(data + 4), h = le16(data + 6);
88	  const uint64_t pixel_bytes = (uint64_t)w * h * 2;
89	  const uint64_t mask_bytes = (uint64_t)((w + 7) / 8) * h;
90	  if (w == 0 || h == 0 || size != 8 + pixel_bytes + mask_bytes) return None;
91	
92	  struct XshimPixmap *colour = pixmap_new((int)w, (int)h, 16);
93	  struct XshimPixmap *mask = pixmap_new((int)w, (int)h, 1);
94	  if (!colour || !mask) {
95	    pixmap_free(colour);
96	    pixmap_free(mask);
97	    return None;
98	  }
99	  for (unsigned i = 0; i < w * h; i++) colour->rgb[i] = px_swap((uint16_t)le16(data + 8 + 2 * i));
100	  memcpy(mask->bits, data + 8 + pixel_bytes, (size_t)mask_bytes);
101	
102	  track(dpy, colour);
103	  track(dpy, mask);
104	  *width_ret = (int)w;
105	  *height_ret = (int)h;
106	  *mask_ret = (Pixmap)(uintptr_t)mask;
107	  return (Pixmap)(uintptr_t)colour;
108	}
