171	static int clipped_out(const GC gc, int64_t x, int64_t y) {
172	  if (!gc->clip) return 0;
173	  const int64_t mx = x - gc->clip_x, my = y - gc->clip_y;
174	  if (mx < 0 || my < 0 || mx >= gc->clip->w || my >= gc->clip->h) return 1;
175	  return !bit_at(gc->clip, (int)mx, (int)my);
