205	/* Copies the part of the rectangle that lies inside both the source and the
206	 * destination (a pixmap, or the canvas when dst is NULL), so a huge width or
207	 * height costs nothing. All sums are in 64 bits. Between a colour source and a
208	 * colour destination, or two bitmaps, pixels are copied as they are; a bitmap
209	 * drawn on the canvas uses the GC's foreground and background. When source and
210	 * destination are the same pixmap and overlap, rows and columns are walked in
211	 * the order that reads each pixel before it is overwritten. */
212	static void copy_region(Display *dpy, GC gc, const struct XshimPixmap *src,
213	                        struct XshimPixmap *dst, int sx, int sy,
214	                        unsigned int w, unsigned int h, int dx, int dy) {
215	  const int64_t dw = dst ? dst->w : dpy->canvas->w;
216	  const int64_t dh = dst ? dst->h : dpy->canvas->h;
217	  const int64_t i0 = max64(0, max64(-(int64_t)sx, -(int64_t)dx));
218	  const int64_t i1 = min64(w, min64((int64_t)src->w - sx, dw - dx));
219	  const int64_t j0 = max64(0, max64(-(int64_t)sy, -(int64_t)dy));
220	  const int64_t j1 = min64(h, min64((int64_t)src->h - sy, dh - dy));
221	  const int same = dst == src;
222	  const int reverse_x = same && dx > sx, reverse_y = same && dy > sy;
223	  for (int64_t jj = 0; jj < j1 - j0; jj++) {
224	    const int64_t j = reverse_y ? j1 - 1 - jj : j0 + jj;
225	    for (int64_t ii = 0; ii < i1 - i0; ii++) {
226	      const int64_t i = reverse_x ? i1 - 1 - ii : i0 + ii;
227	      const int64_t x = dx + i, y = dy + j;
228	      if (clipped_out(gc, x, y)) continue;
229	      const int64_t px = sx + i, py = sy + j;
230	      if (src->depth == 1) {
231	        const int bit = bit_at(src, (int)px, (int)py);
232	        if (!dst)
233	          canvas_point(dpy->canvas, (int)x, (int)y,
234	                       (uint16_t)(bit ? gc->foreground : gc->background));
235	        else
236	          set_bit(dst, (int)x, (int)y, bit);
237	      } else {
238	        const uint16_t colour = src->rgb[py * src->w + px];
239	        if (!dst)
240	          canvas_point(dpy->canvas, (int)x, (int)y, colour);
241	        else
242	          dst->rgb[y * dst->w + x] = colour;
243	      }
244	    }
245	  }
246	}
