248	/* To the canvas, the source must be a colour pixmap. To a pixmap, source and
249	 * destination must have the same depth. Anything else draws nothing, including
250	 * a destination of None: XCreatePixmap returns it when it cannot allocate, and
251	 * a hack that carries on must not paint its sprites on the screen. */
252	int XCopyArea(Display *dpy, Drawable src, Drawable dst, GC gc, int sx, int sy,
253	              unsigned int w, unsigned int h, int dx, int dy) {
254	  const struct XshimPixmap *pm = pixmap_of(src);
255	  struct XshimPixmap *target = pixmap_of(dst);
256	  if (!pm) return 0;
257	  if (!target && dst != WINDOW_ID) return 0;
258	  if (target ? pm->depth == target->depth : pm->depth == 16)
259	    copy_region(dpy, gc, pm, target, sx, sy, w, h, dx, dy);
260	  return 0;
261	}
