115	static void
116	next_point(short *v, XPoint p, int mode)
117	{
118	  switch (mode) {
119	    case CoordModeOrigin:
120	      v[0] = p.x;
121	      v[1] = p.y;
122	      break;
123	    case CoordModePrevious:
124	      v[0] += p.x;
125	      v[1] += p.y;
126	      break;
127	    default:
128	      Assert (False, "next_point: bad mode");
129	      break;
130	  }
